INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1538569-me402', 'stk-anonymous6', 'ME 402', 'info', '{"desc": "Term 231 ( first batch besides the previous summer)\nجودة المقرر بشكل عام: اللاب بصراحة يعتبر ذو فائدة بسيطة جدا بحكم ان اغلب التجارب بسيطة و متكررة فكرتها مع كورسات اخرى.\n\nالمواضيع التي يغطيها المقرر: اللاب يتكون من جزئين، ماتلاب ( نفس لاب ٤١٣ سابقا) و لابفيو ( نفس لاب ٤٥٢ سابقا).\n\nوالتجارب مكررة من الكورسين بتعديلات بسيطة.\nControl:\nبالنسبة لجزئية الماتلاب فاغلبها غير مفيد وبيكون مكرر لاي طالب سبق واخذ كورس يستعمل فيه ماتلاب، مقدمة و شرح لطريقة استعماله.\n\nبعدها يجي لاب بسيط على ال car suspension وهذي التجربة كانت الفاينل لاب لترمنا.\n\nوالتجارب اللي تعتبر جديده على الطالب بالكامل هي تجارب ال Simulink وكيفية استعماله. وهي جزئية جيدة بشكل عام وبسيطة.\n\nMeasurements part:\nبعض اللابات فكرتها ماهي جديدة لكن بتتعلمون كيف تسون التجربه وتسون calibration وتأخذون القراءات.\n\nبالنسبة لجزء اللابفيو labview فكانت شيء جديد على اغلب اذا مو كل الطلاب ولكن بشكل عام اغلب المحاضرين ما كانوا يشرحونها بشكل كويس و شخصيا ما اشوف من البرنامج فائدة للطالب وخاصة على مشارف التخرج.\n\nالكتاب المستخدم للمقرر: لا يوجد\n\nالأسئلة والأمثلة المستخدمة في المقرر: التجارب كلها تقريبا مكررة من الكورسين القديمة ٤١٣ و ٤٥٢.\n\nمدى فائدته في الناحية التطبيقية: بشكل عام جزء كبير من اللاب غير مفيد من وجهة نظري الشخصية. يعني لا تتعلم منه مثلا كيف تصمم كنترولر ( غير مقدمة لاسهل شيء PID ) ولا يعلمك كيف مثلا تستفيد من graphs مثل Bode, Nyquist وغيرها بتحسين الكنترولر. وجزء الlabview مو مرتبط بكورس 401 فقط محشور عشان الطالب يطلع بنفس مخرجات الخطة القديمة.\n\nاضافات:\nبالنسبة لتجارب الماتلاب فهي ايزي ويمدي تخلصها بخلال اللاب اذا انك جديد على الماتلاب بالكامل او ناسيه. واذا لسى تعرف له يمديك تخلص بنص الوقت بالكثير. واذا بتنقش الحلول فما راح تاخذ اكثر من ربع الوقت.\n\nوالكوردنيتور كان ضاغط على المحاضرين ان الطلاب ما يطلعون بدري و ان الموعد النهائي للتسليم يكون بنهاية اللاب ( حسب كلام محاضرنا) بعض المحاضرين كان بالتالي شديد بالنقطتين هذي وبعضهم لا وبعضهم احيان واحيان.\n\nاما الجزء الثاني، فبعض التجارب للامانه ( اللي على البرنامج فقط) يمدي الطالب يخلصها بدري وخلال نص الوقت. لكن اغلب التجارب كانت اننا نروح لكم معمل من معامل القسم و نسوي تجربة بسيطة ونشوف فرق القراءات والخ وهذي كانت تأخذ وقت ولكن ما فيها صعوبة. اغلب التجارب اللي زي كذا كانوا يخلونا نتقسم مجموعات ونسويها و نسوي ريبورت جماعي وتسليمه يكون بعد اسبوع ( من الكوردنيتور محددة).\n\nالكورس فيه مشروعين وفاينل و حول١٢ تجربة.\n\nالمشروع الاول بيكون على labview وبسبب سوء شرح المحاضرين للبرنامج الطلاب واجهوا مشاكل و اشكاليات كثيرة بالمشروع واضطر الكوردنيتور انه يسوي هلب سشن. ما كان فيه على المشروع برزنتيشن وكان دسم ومتطلباته كثيرة ولكن ماهي صعبة للي فهم للبرنامج.\n\nالمشروع الثاني نهاية الترم يكون وهو على الماتلاب ويعتبر اسهل من الاول وعليه برزنتيشن. فيه اعتماد على simulink.\n\nالمشروع يعيبه انه كان بوقت ضغط المشاريع فقط ولا سهل وبسيط مقارنه باللي قبله.\n\nاسئلة المحاضرين في المشروع تركز على تاثير مثلا الPID على rise time او مثلا تاثير الgain اذا زاد على الovershoot.\n\nناسي الشابتر لكنها موجودة باحد الشباتر و سلايدات الدكتور عبدالرحمن العوفي.\n\nالفاينل كان كما ذكرت على جزء الماتلاب فقط وامتنعوا بعض المحاضرين يقولون لنا، ولكن الكورد اكد على ذي النقطة. بالنسبة لنا جانا سؤالين واحد منهم تحل جزء منه بيدك ( derive Equation of Motion ) وترفع صورة حلك بالبلاكبورد والباقي كله على الماتلاب وبتركيز كبير على تطبيق final and initial value\n\nالقريدات باللاب ممتازة جدا والافرج كان حول ٨٠.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-402-measurements-and-control-lab/185070/2", "user": "anonymous6", "ts": 1735382721738, "tid": 185070, "pn": 2}}', 1735382721738, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
